head.script:
scwin.vScrenID = "ULDBNS25001";
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.param2 = "";

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    const param = $c.data.getParameter();

    scwin.param1 = $p.parent().scwin.param1;
    scwin.param2 = $p.parent().scwin.param2;

    console.log("scwin.param1 : "+ scwin.param1);

	//호출파라미터설정
	scwin.setParam();	
	//목록조회
	if(ibx_isurNm.getValue().length > 0) {
        scwin.search();
    } 

};

///////// 3. 컴포넌트 이벤트 영역 /////////
///////// Component Event /////////
scwin.grd_list_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    const isurCd = dlt_list.getCellData(rowIndex, "isurCd");
    const isurNm = dlt_list.getCellData(rowIndex, "isurNm");

    const rtn = {
        isurCd : isurCd ,
        isurNm : isurNm
    }
    console.log(rtn);
    $c.win.closePopup(rtn);
};

scwin.btn_close_onclick = function (e) {
    $c.win.closePopup();
};

scwin.ibx_isurNm_oneditenter = function (e) {
	scwin.search();
};

scwin.btn_search_onclick = function (e) {    
    scwin.search();
};

///////// 4. 서브미션 콜백 영역 /////////
///////// Submission 처리///////// 
scwin.sbm_search_submitdone = function (e) {
    //spa_totCnt.setValue(dlt_list.getRowCount());
};

///////// 5. 일반/업무 함수 영역 /////////
///////// Function /////////
/********************************************** 
* 함수명   : fn_Search
* 설명       : 발행기관을 조회한다.
***********************************************/
scwin.search = async function () {
    const sbmOptions = {
        id : "sbm_search",
        action : "/api/bonds/common/api/code/isuInst-select",
        method : "get",
        ref : "dma_search",
        target : "dlt_list=body",
        gridview : "grd_list",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.sbm_search_submitdone(sbmRtn);
}

/********************************************** 
* 함수명   : fn_SetParam
* 설명       : 부모창에서 받은 데이터를 설정한다.
***********************************************/
scwin.setParam = function () {

    if(scwin.param1 !== undefined  && scwin.param1 !== "") {
        ibx_isurNm.setValue(scwin.param1);
    }else if(scwin.param2 !== undefined  && scwin.param2.length > 0) {
        ibx_isurNm.setValue(scwin.param2);
    }

}
